// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

/**
 * Pins the shutdown-ordering contract of the parallel prefix-run drain (gap-analysis S1): every worker future must be
 * terminal before {@code awaitWorkersBeforeClose} returns, because the caller's {@code finally} closes the shared
 * per-worker LMDB sources immediately afterwards — resetting a read transaction a worker is still iterating is native
 * undefined behaviour. The historical inline loop threw out of its first failed {@code Future#get}, abandoning
 * still-running siblings to exactly that fate; the kernel-aggregate and interpreted-aggregation paths already drain
 * correctly and this contract mirrors theirs.
 */
class LmdbNativeParallelPrefixRunsDrainTest {

	private final ExecutorService executor = Executors.newCachedThreadPool();

	@AfterEach
	void shutDownExecutor() {
		executor.shutdownNow();
	}

	/** A failed sibling must not abandon a still-running worker: the drain returns only once every future is done. */
	@Test
	void drainWaitsForEveryWorkerBeforeReturning() throws Exception {
		AtomicReference<Throwable> failure = new AtomicReference<>();
		IllegalStateException boom = new IllegalStateException("worker failed");
		Future<?> failed = executor.submit(() -> {
			failure.compareAndSet(null, boom);
			throw boom;
		});
		CountDownLatch slowStarted = new CountDownLatch(1);
		AtomicBoolean slowFinished = new AtomicBoolean();
		Future<?> slow = executor.submit(() -> {
			slowStarted.countDown();
			Thread.sleep(150);
			slowFinished.set(true);
			return null;
		});
		slowStarted.await();

		Throwable firstProblem = LmdbNativeParallelPrefixRuns.awaitWorkersBeforeClose(List.of(failed, slow), failure);

		assertThat(slowFinished)
				.as("the drain must not return while a sibling worker still runs — its source would be closed "
						+ "under it")
				.isTrue();
		assertThat(slow.isDone()).isTrue();
		assertThat(firstProblem).as("the sibling's failure is the one reported").isSameAs(boom);
	}

	/**
	 * A query-thread interrupt (timeout/cancel) must stop workers pulling ranges — via the shared failure flag — but
	 * the drain keeps waiting for them to finish, and the interrupt status is restored for the caller.
	 */
	@Test
	void interruptDuringDrainStopsWorkersButKeepsWaiting() throws Exception {
		AtomicReference<Throwable> failure = new AtomicReference<>();
		AtomicBoolean workerFinished = new AtomicBoolean();
		CountDownLatch workerStarted = new CountDownLatch(1);
		// models a worker's range loop: it finishes only once the abort flag is set
		Future<?> worker = executor.submit(() -> {
			workerStarted.countDown();
			while (failure.get() == null) {
				Thread.sleep(2);
			}
			workerFinished.set(true);
			return null;
		});
		workerStarted.await();
		Thread drainThread = Thread.currentThread();
		executor.submit(() -> {
			Thread.sleep(50);
			drainThread.interrupt();
			return null;
		});

		Throwable firstProblem = LmdbNativeParallelPrefixRuns.awaitWorkersBeforeClose(List.of(worker), failure);

		assertThat(Thread.interrupted()).as("the interrupt status is restored for the caller").isTrue();
		assertThat(workerFinished)
				.as("the interrupt reached the abort flag and the drain still waited for the worker")
				.isTrue();
		assertThat(worker.isDone()).isTrue();
		assertThat(firstProblem).isInstanceOf(InterruptedException.class);
	}

	/** A clean run reports no problem and leaves the interrupt status untouched. */
	@Test
	void cleanDrainReportsNoProblem() {
		AtomicReference<Throwable> failure = new AtomicReference<>();
		Future<?> quick = executor.submit(() -> null);

		Throwable firstProblem = LmdbNativeParallelPrefixRuns.awaitWorkersBeforeClose(List.of(quick), failure);

		assertThat(firstProblem).isNull();
		assertThat(Thread.currentThread().isInterrupted()).isFalse();
	}
}
